Generate PDF From HTML.code:
// Render a patient referral letter as a PDF.
// state.data will hold the PDF as a base64 string.
generatePDF(
  // 1) HTML string (or a URL) to convert.
  `<html>
  <body>
    <h1>Referral Letter</h1>
    <p>Patient: ${$.data.patientName}</p>
    <p>Referred to: ${$.data.referralFacility}</p>
    <p>Reason: ${$.data.reason}</p>
  </body>
</html>`,
  // 2) Optional PDFShift options.
  { format: 'A4' }
);

Generate PDF And Get Download Link.code:
// Convert a hosted report page to PDF and get a temporary S3 link.
generatePDF($.data.reportUrl, {
  // With a filename, PDFShift returns JSON with a download url (kept 2 days).
  filename: `monthly-report-${$.data.month}`,
  format: 'A4',
  landscape: true,
});

Generate Certificate In Sandbox.code:
// Test a vaccination certificate layout without spending credits.
generatePDF(
  `<html><body style="text-align:center">
    <h1>Certificate of Vaccination</h1>
    <h2>${$.data.fullName}</h2>
    <p>${$.data.vaccine}, dose ${$.data.doseNumber}, given ${$.data.dateGiven}</p>
  </body></html>`,
  {
    sandbox: true, // watermarked output, free, max 10 docs/minute
    landscape: true,
    format: 'A4',
  }
);

Generate PDF With Header And Footer.code:
// Generate a beneficiary statement with header and page numbers.
generatePDF($.data.statementHtml, {
  format: 'A4',
  margin: '20mm',
  header: {
    source: '<div style="font-size:10px">Cash Transfer Programme Statement</div>',
  },
  footer: {
    // {{page}} and {{total}} are filled in by PDFShift.
    source: '<div style="font-size:10px">Page {{page}} of {{total}}</div>',
  },
});

Convert HTML To PNG.code:
// Render an HTML summary card as a PNG image.
request(
  // 1) HTTP method.
  'POST',
  // 2) Path relative to the PDFShift API base URL.
  '/convert/png',
  // 3) Request body.
  { source: $.data.summaryHtml }
);

Get Credits Usage.code:
// Check credit usage before a large batch run.
request(
  'GET',
  '/credits/usage',
  {}, // no body needed
  { parseAs: 'json' }
);

List Recent Failed Conversions.code:
// List recent failed conversions to debug a job.
request('GET', '/logs', {}, {
  query: { status: 'error', limit: 20 },
  parseAs: 'json',
});
